sys_variable_value.value:
(function execute(inputs, outputs) {
    var attachmentSysId = inputs.attachmentSysId;
    var cleanLines = [];

    if (!attachmentSysId) return;

    try {
        var attachment = new GlideSysAttachment();
        var parser = new sn_impex.GlideExcelParser();
        var attachmentStream = attachment.getContentStream(attachmentSysId);
        
        if (parser.parse(attachmentStream)) {
            while (parser.next()) {
                var row = parser.getRow();
                
                // Extract columns exactly matching your Excel headers
                var catItem  = row['Cat item'] ? row['Cat item'].trim() : '';
                var adGroup  = row['ad group'] ? row['ad group'].trim() : '';
                var license  = row['license required'] ? row['license required'].trim() : '';
                var scripted = row['scripted'] ? row['scripted'].trim() : '';
                
                if (catItem) {
                    // Stringify the data fields into a standard pipe-separated line 
                    // to easily parse back out in the flow loop
                    cleanLines.push(catItem + "||" + adGroup + "||" + license + "||" + scripted);
                }
            }
        }
    } catch(ex) {
        gs.error("Excel Parse Action Error: " + ex.getMessage());
    }

    outputs.row_array = cleanLines;
})(inputs, outputs);

